package team.warden.mobile

import android.app.Activity
import android.os.Bundle
import android.util.Log

// Story 12.2 — headless bench trigger. DEBUG VARIANTS ONLY.
// Generated by with-detection-engine.js; tracked source is plugins/kotlin/.
//
// Declared in `android/app/src/debug/AndroidManifest.xml`, so the manifest merger
// never puts an exported component into a release build. It ALSO checks
// BuildConfig.DEBUG at runtime — a manifest overlay is easy to get wrong and the
// second check costs one line.
//
// It STAYS ON SCREEN while the bench runs and finishes only when the worker
// thread is done. That is not cosmetic: a `Theme.NoDisplay` activity must call
// finish() before onResume() completes (the framework throws otherwise), and a
// backgrounded process would face the low-memory killer and a different governor
// policy part-way through a multi-minute measurement — silently distorting the
// thermal/sustained-clock context AC11 asks for.
//
//   adb shell am start -n team.warden.mobile/.WardenEngineBenchActivity \
//     --es mode all \
//     --es video /sdcard/warden12_2/capture.mp4 \
//     --ei limit 0 --ei cpuFrames 400
//
// The work runs on a WORKER THREAD, not the UI thread — which is AC16's point:
// the EGL context is thread-bound and needs no Activity at all. The Activity is
// only an adb-reachable entry point.
class WardenEngineBenchActivity : Activity() {

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        if (!BuildConfig.DEBUG) {
            Log.e(TAG, "bench is debug-only; refusing to run")
            finish()
            return
        }
        val mode = intent.getStringExtra("mode") ?: "all"
        val video = intent.getStringExtra("video")
        val limit = intent.getIntExtra("limit", 0)
        val cpuFrames = intent.getIntExtra("cpuFrames", 400)

        // 🔴 REVIEW 2026-09-15: a configuration change (no orientation lock is
        // declared, and this ignored savedInstanceState) re-entered onCreate and
        // started a SECOND bench — its own EGL context, the same artifact
        // filenames, and two runs contending for the GPU while each reports
        // "sustained clocks". Shares the latch with the RN bridge, because the two
        // entry points can also collide with each other.
        if (!WardenDetectionEngineModule.benchInFlight.compareAndSet(false, true)) {
            Log.e(TAG, "a bench run is already in flight; refusing to start a second")
            finish()
            return
        }

        Log.i(TAG, "BENCH START mode=$mode video=$video limit=$limit cpuFrames=$cpuFrames")
        // Keep the screen on: a display timeout mid-run drops the process's
        // priority and changes the very clocks being measured.
        window.addFlags(android.view.WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON)
        val app = applicationContext
        Thread({
            try {
                val report = WardenEngineBench(app).runAll(mode, video, limit, cpuFrames)
                // Logged in chunks: logcat truncates a single line around 4 kB and a
                // silently-cut JSON report reads as a corrupt run.
                val s = report.toString()
                var i = 0
                while (i < s.length) {
                    val end = minOf(i + 3000, s.length)
                    Log.i(TAG, "REPORT[$i:$end] ${s.substring(i, end)}")
                    i = end
                }
                Log.i(TAG, "BENCH DONE")
            } catch (t: Throwable) {
                Log.e(TAG, "BENCH FAILED", t)
            } finally {
                WardenDetectionEngineModule.benchInFlight.set(false)
                finish()
            }
        }, "warden-bench").start()
    }

    companion object {
        private const val TAG = "WardenBench"
    }
}
